// ═══ DATA RACE: no happens-before ═══
int shared = 0;  // NOT volatile, NOT synchronized
// Thread-1: shared = 42;
// Thread-2: int x = shared;
// DATA RACE! No happens-before between write and read!
// Thread-2 may see 0, 42, or even a TORN value (on 64-bit long without volatile)!
// FIX: volatile int shared; OR synchronized access

// ═══ RACE CONDITION: timing-dependent logic ═══
volatile int balance = 100000;  // volatile → no DATA RACE!
// Thread-1: if (balance >= 70000) balance -= 70000;
// Thread-2: if (balance >= 70000) balance -= 70000;
// No data race (volatile ensures visibility)!
// BUT: race condition! Both read 100000, both pass check, both debit → overdraft!
// FIX: synchronized { if (balance >= amount) balance -= amount; }

// ═══ DATA RACE WITHOUT RACE CONDITION ═══
int counter = 0;  // NOT volatile
// Thread-1: counter = 1;
// Thread-2: counter = 2;
// DATA RACE: no happens-before!
// But: we don't CARE which value wins — either 1 or 2 is fine.
// Logic is correct regardless of who writes last. No race CONDITION.
// (Still a data race — technically undefined behavior under JMM!)

// ═══ RACE CONDITION WITHOUT DATA RACE ═══
synchronized (lock) { int size = map.size(); }  // read size (synchronized)
synchronized (lock) { map.put(key, value); }     // put (synchronized)
// No data race: each operation is synchronized!
// BUT: between the two synchronized blocks, another thread may put → size changed!
// Race condition on the COMPOUND check-then-act!
// FIX: synchronized (lock) { if (map.size() < max) map.put(key, value); }

// ═══ SUMMARY ═══
// Data race:       JMM violation. Fix: volatile/synchronized/Lock.
// Race condition:  Logic bug. Fix: make compound operation atomic.
// Both together:   most common (unsynchronized read-modify-write)
// Data race only:  rare (write that doesn't affect correctness)
// Race condition only: synchronized individual ops but compound not atomic
