// ─── File: src/test/java/com/bank/races/DataRaceVsRaceConditionTest.java ───
package com.bank.races;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class DataRaceVsRaceConditionTest {

    // ═══ DATA RACE: no volatile, corrupted read ═══
    @Test
    void dataRace_noVolatile() throws InterruptedException {
        int[] shared = {0};  // NOT volatile!
        CountDownLatch done = new CountDownLatch(2);

        new Thread(() -> { shared[0] = 42; done.countDown(); }).start();
        new Thread(() -> {
            int read = shared[0];  // may see 0 or 42 — undefined!
            done.countDown();
        }).start();
        done.await();
        // No guarantee what Thread-2 reads! DATA RACE!
    }

    // ═══ RACE CONDITION: volatile but compound not atomic ═══
    @Test
    void raceCondition_volatileButCompoundNotAtomic() throws InterruptedException {
        AtomicInteger balance = new AtomicInteger(100);  // no data race (atomic)!
        AtomicInteger overdrafts = new AtomicInteger(0);

        for (int trial = 0; trial < 100; trial++) {
            balance.set(100);
            CountDownLatch latch = new CountDownLatch(2);

            Runnable withdraw = () -> {
                int current = balance.get();           // atomic read
                if (current >= 70) {                   // check
                    // RACE WINDOW! Other thread also passed check!
                    balance.addAndGet(-70);             // act
                }
                latch.countDown();
            };

            new Thread(withdraw).start();
            new Thread(withdraw).start();
            latch.await();

            if (balance.get() < 0) overdrafts.incrementAndGet();
        }
        System.out.println("Overdrafts: " + overdrafts.get() + "/100");
        // Some overdrafts! Race CONDITION (not data race — AtomicInteger is safe!)
    }

    // ═══ FIX: atomic compareAndSet for compound operation ═══
    @Test
    void fix_atomicCompareAndSet() throws InterruptedException {
        AtomicInteger balance = new AtomicInteger(100);

        for (int trial = 0; trial < 100; trial++) {
            balance.set(100);
            CountDownLatch latch = new CountDownLatch(2);

            Runnable safeWithdraw = () -> {
                int current;
                do {
                    current = balance.get();
                    if (current < 70) { latch.countDown(); return; }
                } while (!balance.compareAndSet(current, current - 70));
                // CAS: check AND act ATOMICALLY!
                latch.countDown();
            };

            new Thread(safeWithdraw).start();
            new Thread(safeWithdraw).start();
            latch.await();

            assertThat(balance.get()).isGreaterThanOrEqualTo(0);  // NEVER negative!
        }
    }

    // ═══ Neither: properly synchronized ═══
    @Test
    void neitherRace_fullySynchronized() throws InterruptedException {
        int[] balance = {100};
        Object lock = new Object();

        for (int trial = 0; trial < 100; trial++) {
            balance[0] = 100;
            CountDownLatch latch = new CountDownLatch(2);

            Runnable withdraw = () -> {
                synchronized (lock) {
                    if (balance[0] >= 70) balance[0] -= 70;
                    // Check + act INSIDE one synchronized → no race condition!
                    // Synchronized → no data race!
                }
                latch.countDown();
            };

            new Thread(withdraw).start();
            new Thread(withdraw).start();
            latch.await();
            assertThat(balance[0]).isGreaterThanOrEqualTo(0);
        }
    }
}
